<script setup lang="ts">
import {computed,onMounted,reactive,ref} from "vue";
import {useI18n} from "vue-i18n";
import {ElMessage} from "element-plus";
import {AppIcon} from "@appnexus/icons";
import {BusinessWorkspace,ManagedDialog,ManagementTable,type ManagementColumn} from "@appnexus/ui";
import type {RoleCreate,RoleItem,RoleManagementApi,RoleStatus,RoleType} from "./index";
const props=defineProps<{api:RoleManagementApi;errorText:(error:unknown)=>string}>();
const {t,d}=useI18n();
const rows=ref<RoleItem[]>([]),total=ref(0),loading=ref(false),saving=ref(false),error=ref("");
const query=reactive<{query:string;status:""|RoleStatus;roleType:""|RoleType;page:number;pageSize:number}>({query:"",status:"",roleType:"",page:1,pageSize:20});
const submitted=reactive({...query});const dialog=ref<"create"|"edit"|"status"|"delete"|"">("");const selected=ref<RoleItem>();
const form=reactive<RoleCreate>({code:"",name:"",description:"",sortOrder:100});const formRef=ref<{validate:()=>Promise<boolean>}|null>(null);const reason=ref(""),confirmation=ref("");
/** 前端校验用于即时反馈，服务端仍是角色字段约束的最终权威。 */
const formRules=computed(()=>({code:[{required:true,message:t("roleManagement.validation.codeRequired"),trigger:"blur"},{pattern:/^(?!sys_)[a-z][a-z0-9_]{1,63}$/,message:t("roleManagement.validation.codeInvalid"),trigger:"blur"}],name:[{required:true,whitespace:true,message:t("roleManagement.validation.nameRequired"),trigger:"blur"},{max:100,message:t("roleManagement.validation.nameTooLong"),trigger:"blur"}],description:[{max:500,message:t("roleManagement.validation.descriptionTooLong"),trigger:"blur"}],sortOrder:[{required:true,message:t("roleManagement.validation.sortRequired"),trigger:"change"}]}));
const columns=computed<ManagementColumn[]>(()=>[{key:"name",prop:"name",label:t("roleManagement.name"),minWidth:160},{key:"code",prop:"code",label:t("roleManagement.code"),minWidth:170},{key:"roleType",label:t("roleManagement.type"),width:120},{key:"status",label:t("roleManagement.status"),width:110},{key:"description",prop:"description",label:t("roleManagement.description"),minWidth:180},{key:"sortOrder",prop:"sortOrder",label:t("roleManagement.sortOrder"),width:100},{key:"updatedAt",label:t("roleManagement.updatedAt"),minWidth:180},{key:"operations",label:t("tenant.operation"),width:240,fixed:"right"}]);
async function load(){loading.value=true;error.value="";try{const page=await props.api.list({query:submitted.query,status:submitted.status||undefined,roleType:submitted.roleType||undefined,page:submitted.page,pageSize:submitted.pageSize});rows.value=page.items;total.value=page.total;}catch(cause){error.value=props.errorText(cause);}finally{loading.value=false;}}
function search(reset=false){if(reset)Object.assign(query,{query:"",status:"",roleType:"",page:1,pageSize:20});Object.assign(submitted,query,{page:1});load();}
function openCreate(){selected.value=undefined;Object.assign(form,{code:"",name:"",description:"",sortOrder:100});dialog.value="create";}
function openEdit(row:RoleItem){selected.value=row;Object.assign(form,{code:row.code,name:row.name,description:row.description||"",sortOrder:row.sortOrder});dialog.value="edit";}
function openStatus(row:RoleItem){selected.value=row;reason.value="";dialog.value="status";}
function openDelete(row:RoleItem){selected.value=row;reason.value="";confirmation.value="";dialog.value="delete";}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;error.value="";try{if(dialog.value==="edit"&&selected.value)await props.api.update(selected.value.id,{name:form.name,description:form.description,sortOrder:form.sortOrder,version:selected.value.version});else await props.api.create({...form});dialog.value="";ElMessage.success(t("roleManagement.saved"));await load();}catch(cause){error.value=props.errorText(cause);}finally{saving.value=false;}}
async function changeStatus(){if(!selected.value)return;const target:RoleStatus=selected.value.status==="ENABLED"?"DISABLED":"ENABLED";if(target==="DISABLED"&&!reason.value.trim())return;saving.value=true;try{await props.api.changeStatus(selected.value.id,target,reason.value,selected.value.version);dialog.value="";ElMessage.success(t("roleManagement.statusSaved"));await load();}catch(cause){error.value=props.errorText(cause);}finally{saving.value=false;}}
async function remove(){if(!selected.value||confirmation.value!==selected.value.code||!reason.value.trim())return;saving.value=true;try{await props.api.remove(selected.value.id,confirmation.value,reason.value,selected.value.version);dialog.value="";ElMessage.success(t("roleManagement.deleted"));if(rows.value.length===1&&submitted.page>1)submitted.page--;await load();}catch(cause){error.value=props.errorText(cause);}finally{saving.value=false;}}
onMounted(load);
</script>
<template><div class="management-page"><BusinessWorkspace :title="t('roleManagement.title')" :description="t('roleManagement.descriptionText')">
 <template v-if="error&&!dialog" #feedback><el-alert type="error" :title="error" :closable="false" show-icon><el-button link type="primary" @click="load">{{t('account.retry')}}</el-button></el-alert></template>
 <template #search><div class="management-filter"><div class="management-filter-header"><h2 class="management-filter-title">{{t('roleManagement.query')}}</h2></div><el-form inline @submit.prevent="search()"><el-form-item :label="t('management.keyword')"><el-input v-model="query.query" clearable :maxlength="100" :placeholder="t('roleManagement.queryPlaceholder')" /></el-form-item><el-form-item :label="t('roleManagement.status')"><el-select v-model="query.status" class="role-filter-select" clearable :placeholder="t('roleManagement.allStatuses')"><el-option v-for="value in ['ENABLED','DISABLED']" :key="value" :label="t('roleManagement.statuses.'+value)" :value="value" /></el-select></el-form-item><el-form-item :label="t('roleManagement.type')"><el-select v-model="query.roleType" class="role-filter-select" clearable :placeholder="t('roleManagement.allTypes')"><el-option v-for="value in ['SYSTEM','CUSTOM']" :key="value" :label="t('roleManagement.types.'+value)" :value="value" /></el-select></el-form-item><div class="management-filter-actions"><el-button type="primary" native-type="submit"><AppIcon name="search" :size="16" class="mr-1" />{{t('administration.search')}}</el-button><el-button @click="search(true)"><AppIcon name="refresh" :size="16" class="mr-1" />{{t('management.reset')}}</el-button></div></el-form></div></template>
 <template #data><ManagementTable embedded :title="t('roleManagement.list')" :rows="rows" :columns="columns" :total="total" :loading="loading" :busy="saving" :empty-text="t(submitted.query||submitted.status||submitted.roleType?'management.noResults':'roleManagement.empty')" @refresh="load"><template #actions><el-button v-operation="'@role:create'" type="primary" @click="openCreate"><AppIcon name="add" :size="16" class="mr-1" />{{t('roleManagement.create')}}</el-button></template><template #roleType="{row}"><el-tag type="info">{{t('roleManagement.types.'+row.roleType)}}</el-tag></template><template #status="{row}"><el-tag :type="row.status==='ENABLED'?'success':'info'">{{t('roleManagement.statuses.'+row.status)}}</el-tag></template><template #description="{row}">{{row.description||'—'}}</template><template #updatedAt="{row}">{{d(new Date(row.updatedAt),'long')}}</template><template #operations="{row}"><el-button v-operation="'@role:update'" link type="primary" @click="openEdit(row)">{{t('roleManagement.edit')}}</el-button><el-button v-operation="'@role:enable'" link :type="row.status==='ENABLED'?'warning':'success'" @click="openStatus(row)">{{t(row.status==='ENABLED'?'roleManagement.disable':'roleManagement.enable')}}</el-button><el-button v-operation="'@role:delete'" link type="danger" :disabled="row.roleType==='SYSTEM'||row.status!=='DISABLED'" @click="openDelete(row)">{{t('roleManagement.delete')}}</el-button></template><template #pagination><el-pagination v-model:current-page="submitted.page" v-model:page-size="submitted.pageSize" :total="total" :page-sizes="[20,50,100]" layout="total, sizes, prev, pager, next" @change="load" /></template></ManagementTable></template>
 </BusinessWorkspace>
 <ManagedDialog :model-value="dialog==='create'||dialog==='edit'" :title="t(dialog==='edit'?'roleManagement.edit':'roleManagement.create')" width="min(680px, calc(100vw - 32px))" :busy="saving" @update:model-value="v=>{if(!v)dialog=''}"><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb-4" /><el-form ref="formRef" :model="form" :rules="formRules" label-position="top" @submit.prevent="save"><el-form-item :label="t('roleManagement.type')"><div class="role-readonly">{{t('roleManagement.types.'+(selected?.roleType||'CUSTOM'))}}</div><small v-if="dialog==='create'">{{t('roleManagement.typeHint')}}</small></el-form-item><el-form-item prop="code" :label="t('roleManagement.code')"><div v-if="dialog==='edit'" class="role-readonly">{{form.code}}</div><el-input v-else v-model="form.code" :maxlength="64" /><small>{{t('roleManagement.codeHint')}}</small></el-form-item><el-form-item prop="name" :label="t('roleManagement.name')"><el-input v-model="form.name" :maxlength="100" /></el-form-item><el-form-item prop="description" :label="t('roleManagement.description')"><el-input v-model="form.description" type="textarea" :maxlength="500" show-word-limit /></el-form-item><el-form-item prop="sortOrder" :label="t('roleManagement.sortOrder')"><el-input-number v-model="form.sortOrder" :min="0" :max="9999" /></el-form-item><div class="flex justify-end gap-2"><el-button @click="dialog=''">{{t('organization.cancel')}}</el-button><el-button v-operation="dialog==='create'?'@role:create':'@role:update'" type="primary" native-type="submit" :loading="saving">{{t('organization.save')}}</el-button></div></el-form></ManagedDialog>
 <ManagedDialog :model-value="dialog==='status'" :title="t(selected?.status==='ENABLED'?'roleManagement.disable':'roleManagement.enable')" width="min(560px, calc(100vw - 32px))" :busy="saving" @update:model-value="v=>{if(!v)dialog=''}"><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb-4" /><p>{{selected?.name}}（{{selected?.code}}）</p><el-form label-position="top" @submit.prevent="changeStatus"><el-form-item :label="t('roleManagement.reason')" :required="selected?.status==='ENABLED'"><el-input v-model="reason" type="textarea" :maxlength="500" show-word-limit /></el-form-item><div class="flex justify-end gap-2"><el-button @click="dialog=''">{{t('organization.cancel')}}</el-button><el-button v-operation="'@role:enable'" :type="selected?.status==='ENABLED'?'danger':'primary'" native-type="submit" :loading="saving">{{t(selected?.status==='ENABLED'?'roleManagement.disable':'roleManagement.enable')}}</el-button></div></el-form></ManagedDialog>
 <ManagedDialog :model-value="dialog==='delete'" :title="t('roleManagement.delete')" width="min(560px, calc(100vw - 32px))" :busy="saving" @update:model-value="v=>{if(!v)dialog=''}"><el-alert type="warning" :title="t('roleManagement.deleteHint')" :closable="false" show-icon class="mb-4" /><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb-4" /><el-form label-position="top" @submit.prevent="remove"><el-form-item :label="t('roleManagement.confirmCode')"><el-input v-model="confirmation" :placeholder="selected?.code" /></el-form-item><el-form-item :label="t('roleManagement.reason')" required><el-input v-model="reason" type="textarea" :maxlength="500" show-word-limit /></el-form-item><div class="flex justify-end gap-2"><el-button @click="dialog=''">{{t('organization.cancel')}}</el-button><el-button v-operation="'@role:delete'" type="danger" native-type="submit" :disabled="confirmation!==selected?.code||!reason.trim()" :loading="saving">{{t('roleManagement.delete')}}</el-button></div></el-form></ManagedDialog>
</div></template>
<style scoped>.role-filter-select{width:180px}.role-readonly{font-family:monospace;color:var(--el-text-color-regular)}small{display:block;color:var(--el-text-color-secondary);margin-top:4px}@media(max-width:600px){.role-filter-select{width:100%}:deep(.el-button){min-height:44px}}</style>
